from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message
import json
import re
import pandas as pd
import joblib


class PredictFailure(Component):
    display_name = "Predict Failure"
    description = "Predicts failure type."
    icon = "cpu"

    inputs = [
        MessageTextInput(
            name="input_value",
            display_name="Input",
        )
    ]

    outputs = [
        Output(display_name="Output", name="output", method="run")
    ]

    def run(self) -> Message:
        raw = self.input_value
        if hasattr(raw, 'text'):
            raw = raw.text
        raw = str(raw).strip()

        match = re.search(r'\{.*\}', raw, re.DOTALL)
        if not match:
            return Message(text="ERROR: No JSON found")

        try:
            data = json.loads(match.group())
        except Exception as e:
            return Message(text=f"ERROR: {e}")

        type_map = {"L": 0, "M": 1, "H": 2}
        air  = float(data.get("AirTemp", 300))
        proc = float(data.get("ProcessTemp", 310))
        rpm  = float(data.get("RPM", 1500))
        torq = float(data.get("Torque", 40))
        wear = float(data.get("ToolWear", 100))
        mtype = type_map.get(data.get("Type", "M"), 1)

        df = pd.DataFrame({
            "Type":                     [mtype],
            "Air temperature [K]":      [air],
            "Process temperature [K]":  [proc],
            "Rotational speed [rpm]":   [rpm],
            "Torque [Nm]":              [torq],
            "Tool wear [min]":          [wear],
            "Temperature_Difference":   [proc - air],
            "Power":                    [rpm * torq],
            "Wear_Rate":                [wear / (rpm + 1)],
        })

        try:
            model = joblib.load("predictive_maintenance_model.pkl")
            pred = int(model.predict(df)[0])
        except FileNotFoundError:
            return Message(text="ERROR: Model file not found")
        except Exception as e:
            return Message(text=f"ERROR: {e}")

        return Message(text=str(pred))

from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message


class MapFailure(Component):
    display_name = "Map Failure"
    description = "Maps integer to failure name."
    icon = "map"

    inputs = [
        MessageTextInput(
            name="input_value",
            display_name="Input",
        )
    ]

    outputs = [
        Output(display_name="Output", name="output", method="run")
    ]

    def run(self) -> Message:
        raw = self.input_value
        if hasattr(raw, 'text'):
            raw = raw.text
        raw = str(raw).strip()

        mapping = {
            "0": "Heat Dissipation Failure",
            "1": "No Failure",
            "2": "Overstrain Failure",
            "3": "Power Failure",
            "4": "Random Failure",
            "5": "Tool Wear Failure",
        }

        return Message(text=mapping.get(raw, f"Unknown: {raw}"))
